INSERT INTO grammar_patterns (slug, label, tooltip, endings) VALUES
    ('carry-along', 'Carry-along', 'Marks the result of the action as carried toward (오다) or away from (가다) a reference point — literal transport or figurative continuity — as one fused event, distinct from a loosely sequenced -아/어서 pair of clauses and from the leave-in-place nuance of -아/어 놓다.', '-아/어 오다, -아/어 가다');
